Plan: read the cached values from the active sheet, test each row’s S cell for an Excel error, and apply the U-cell difference rules to write plain text results into R2:R20. The script will treat `#N/A`-style errors as “Upload”, values from -1 to 1 as “Do not Upload”, and values greater than 1 as “to Check”.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active if wb.active is not None else wb.worksheets[0]
vws = vals[ws.title]

ERROR_CODES = {
    "#N/A", "#DIV/0!", "#VALUE!", "#REF!", "#NAME?", "#NULL!", "#NUM!"
}

def is_error_value(value):
    if value is None:
        return False
    if isinstance(value, str):
        v = value.strip()
        return v in ERROR_CODES or v.lower() == "error"
    return False

results = []
for row in range(2, 21):
    s_val = vws.cell(row=row, column=19).value  # S
    u_val = vws.cell(row=row, column=21).value  # U

    if is_error_value(s_val):
        result = "Upload"
    else:
        try:
            u_num = float(u_val)
        except (TypeError, ValueError):
            u_num = None

        if u_num is not None:
            if -1 <= u_num <= 1:
                result = "Do not Upload"
            elif u_num > 1:
                result = "to Check"
            else:
                result = None
        else:
            result = None

    ws.cell(row=row, column=18).value = result  # R
    results.append(result)

print("Rows written:", len(results))
print("Sample results:", results[:5])

wb.save(OUT)
